const SessionTimeoutManager={logoutTimer:null,warningTimer:null,lastActivity:Date.now(),lastArmed:0,events:['pointerdown','pointermove','keydown','scroll','wheel','touchstart'],minutes(){return Math.max(5,Math.min(480,Number(ApplicationSettings.system?.sessionTimeout)||30))},reset(){this.lastActivity=Date.now();this.hideWarning();if(Date.now()-this.lastArmed>1000)this.arm()},arm(){clearTimeout(this.logoutTimer);clearTimeout(this.warningTimer);if(!liveProfile)return;this.lastArmed=Date.now();const minutes=this.minutes(),warningMinutes=Math.max(1,Math.min(30,Number(ApplicationSettings.system?.sessionWarning)||1)),duration=minutes*60000,warningAt=Math.max(1000,duration-Math.min(warningMinutes,minutes-1)*60000);this.warningTimer=setTimeout(()=>this.warn(warningMinutes),warningAt);this.logoutTimer=setTimeout(()=>this.logout(),duration)},warn(minutes=1){if(!liveProfile||Date.now()-this.lastActivity<(this.minutes()-minutes)*60000)return;let box=document.getElementById('sessionTimeoutWarning');if(!box){box=document.createElement('div');box.id='sessionTimeoutWarning';box.className='session-timeout-warning';document.body.appendChild(box)}box.innerHTML=`<strong>Session ending soon</strong><p>You will be signed out in ${minutes} minute${minutes===1?'':'s'} because there has been no activity.</p><button type="button" class="je-btn je-btn-emerald" onclick="SessionTimeoutManager.reset()">Stay Signed In</button>`;box.hidden=false},hideWarning(){const box=document.getElementById('sessionTimeoutWarning');if(box)box.hidden=true},async logout(){if(!liveProfile)return;if(Date.now()-this.lastActivity<this.minutes()*60000){this.arm();return}this.hideWarning();showCenterStatus('Session expired. Please sign in again.');await logoutDemoUser()}};
function startSessionTimeoutManager(){SessionTimeoutManager.arm()}

function initializeFoundationControls(){
  const form=document.getElementById('businessSettingsForm');form?.addEventListener('input',reconcileBusinessDirtyState);
  setBusinessSettingsBaseline();
  SessionTimeoutManager.events.forEach(name=>document.addEventListener(name,()=>{if(liveProfile)SessionTimeoutManager.reset()},{passive:true}));
  window.addEventListener('focus',()=>{if(liveProfile)SessionTimeoutManager.check1434?.()});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden&&liveProfile)SessionTimeoutManager.check1434?.()});
  document.addEventListener('click',event=>{if(!event.target.closest('.sub-user-search-wrap')){const results=document.getElementById('subUserSearchResults');if(results)results.hidden=true}});
  const active=document.querySelector('.tab-content.active')?.id||'dashboard';updateSettingsBrowser(active);updateGlobalExportTools(active);
}
