function validateReport71(r,finish){
 if(r.statement!==''&&(!Number.isFinite(Number(r.statement))||Math.abs(Number(r.statement)*100-Math.round(Number(r.statement)*100))>0.00001))throw Error('Enter a valid statement balance.');
 for(const f of r.findings){if(f.amount===''||!Number.isFinite(Number(f.amount))||Math.abs(Number(f.amount)*100-Math.round(Number(f.amount)*100))>0.00001||!f.description.trim())throw Error('Each finding needs an amount with at most two decimal places and an explanation.');if(f.entryId&&!r.lines.some(l=>l.id===f.entryId))throw Error('Linked entry '+f.entryId+' is not in this account snapshot. Refresh the ledger figures after posting a correction.');}
 if(!finish)return;
 if(r.statement==='')throw Error('Enter the statement closing balance.');
 if(!r.statementReference.trim()&&!r.attachments.length)throw Error('Enter a statement reference or attach your statement.');
 if(reportCalculation71(r).difference!==0)throw Error('The unexplained difference must be zero before finishing.');
 if(r.findings.some(f=>f.kind==='unexplained'||f.status==='investigating'||(f.kind==='correction'&&(!f.entryId||f.status!=='resolved'))||(f.kind==='outstanding'&&f.status!=='outstanding')))throw Error('Resolve unexplained findings. Timing items must be Outstanding; corrections must be Resolved with a linked posted entry.');
}
async function saveReport71(finish){if(reportAttaching71)return recError71('Wait for the attachment to finish loading before saving.');if(reportBusy71||currentReport71?.status!=='draft')return;reportBusy71=true;try{if(!reportPermission71()||currentReport71.owner!==reportOwner71())throw Error('Report access is not available.');validateReport71(currentReport71,finish);if(finish){if(liveProfile)await loadJournalFromSupabase();const saved={...Accounts69};try{Accounts69.from=currentReport71.from;Accounts69.to=currentReport71.to;const latest=accountData69().find(a=>a.key===currentReport71.accountKey);const signature=x=>JSON.stringify([x.opening,x.closing,x.lines.map(l=>[l.id,l.date,l.memo,l.dr,l.cr])]);if(!latest||signature(latest)!==signature(currentReport71))throw Error('The ledger has changed. Refresh Ledger Figures, review the differences, then finish again.')}finally{Object.assign(Accounts69,saved)}}const copy=structuredClone(currentReport71);copy.status=finish?'reconciled':'draft';copy.updatedAt=new Date().toISOString();if(finish){copy.completedAt=copy.updatedAt;copy.completedBy=preparer71()}copy.key=copy.owner+':'+copy.id;await reportStore71('readwrite',s=>s.put(copy));currentReport71=copy;renderReport71();recError71(finish?'Reconciliation saved. This snapshot is now read-only.':'Draft saved in this browser.');await renderReconciliationList71()}catch(e){recError71('Not saved: '+e.message)}finally{reportBusy71=false}}
