async function attachReportFiles71(input){if(currentReport71?.status!=='draft')return;const report=currentReport71;reportAttaching71=true;try{for(const f of input.files){if(!['application/pdf','image/png','image/jpeg'].includes(f.type)||f.size>10*1024*1024)throw Error('Use PDF, PNG or JPEG files up to 10 MB each.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(f)});report.attachments.push({name:f.name,type:f.type,data})}if(currentReport71===report)renderReport71()}catch(e){recError71(e.message)}finally{reportAttaching71=false}}
