async function importReport71(input){try{const file=input.files[0];if(!file)return;if(file.size>50*1024*1024)throw Error('Backup exceeds 50 MB.');const data=JSON.parse(await file.text()),r=data.report;if(data.format!=='oonjai-reconciliation-1'||!r||!Array.isArray(r.lines)||!Array.isArray(r.findings)||!Array.isArray(r.attachments)||!r.account?.name||!['draft','reconciled'].includes(r.status)||!Number.isSafeInteger(r.closing))throw Error('Invalid report backup.');if(r.attachments.some(a=>!/^data:(application\/pdf|image\/png|image\/jpeg);base64,[A-Za-z0-9+/=]+$/.test(a.data)))throw Error('Unsupported attachment in backup.');validateReport71(r,r.status==='reconciled');r.originalReportId=r.id;r.id='REC-'+crypto.randomUUID();r.owner=reportOwner71();r.key=r.owner+':'+r.id;r.updatedAt=new Date().toISOString();r.importedAt=r.updatedAt;await reportStore71('readwrite',s=>s.put(r));await renderReconciliationList71()}catch(e){showAppNotification('Import failed',e.message,true)}finally{input.value=''}}
