function printHtml82(title,content,period=''){
 const s=ApplicationSettings.printing||{},company=BusinessSettings.current?.companyName||AccountingStore.companyName||'Oon Jai Accounting',paper=['A4','Letter','Legal'].includes(s.paperSize)?s.paperSize:'A4',orientation=s.orientation==='landscape'?'landscape':'portrait',margin={narrow:8,normal:14,wide:22}[s.marginSize]||14;
 const img=(value,alt)=>/^data:image\/(png|jpeg|webp);base64,/i.test(value||'')?`<img class="brand82" src="${esc82(value)}" alt="${alt}">`:'';
 const header=img(PrintSettings.headerImage,'Business letterhead'),footer=img(PrintSettings.footerImage,'Business footer');
 const name=(s.fileNamePattern==='business-report-date'?company+'-':'')+title+'-'+(s.fileNamePattern==='report-period'?period:today82());
 const pageNumbers=s.showPageNumbers?`@bottom-right{content:${s.pageNumberFormat==='page-total'?'"Page " counter(page) " of " counter(pages)':'"Page " counter(page)'};font:9px Arial;color:#627469}`:'';
 return `<!doctype html><html><head><meta charset="utf-8"><title>${esc82(name)}</title><style>@page{size:${paper} ${orientation};margin:${margin}mm;${pageNumbers}}*{box-sizing:border-box}body{font:10px Arial,sans-serif;color:#18392e;margin:0}h1{font-size:20px;margin:8px 0}h2{font-size:17px;margin:6px 0}h3{font-size:15px}h4{font-size:12px;margin:0;padding:7px 0;border-top:3px solid #059669}p{line-height:1.5;white-space:pre-wrap}table{width:100%;border-collapse:collapse}th,td{border:1px solid #c6d9ce;padding:5px;text-align:left;overflow-wrap:anywhere}th{background:#e8f5ec;text-align:left}.amount82{white-space:nowrap;overflow-wrap:normal}thead{display:table-header-group}tfoot{display:table-footer-group}tr{break-inside:avoid}table.print-shell82>tbody>tr{break-inside:auto}table.print-shell82>tbody>tr>td,table.print-shell82>thead>tr>td,table.print-shell82>tfoot>tr>td{border:0;padding:0}.brand82{display:block;width:100%;max-height:30mm;object-fit:contain}.block82{margin:12px 0}.block82 header{break-after:avoid}.metric82{display:flex;gap:25px;padding:10px 0}.metric82 small,.metric82 strong{display:block}.notice82{padding:7px;background:#f0f7f2;line-height:1.5}.signatures82{display:flex;justify-content:space-between;gap:25px;margin-top:25px;padding-top:8px}.signatures82>div{flex:1;border-top:1px solid #799382;padding-top:7px}.voucher82{break-after:page}.voucher82:last-child{break-after:auto}.negative82,.warn82{color:#a52b22}.statement82{border-top:3px solid #059669;margin:14px 0}.statement82>header,.statement-total82{display:flex;justify-content:space-between;padding:8px}.statement82 table{table-layout:auto}button,.actions82{display:none}.r79-metrics{display:flex;gap:24px}.r79-metrics small,.r79-metrics strong{display:block}</style></head><body><table class="print-shell82">${s.headerPlacement==='all'?'<thead><tr><td>'+header+'</td></tr></thead>':''}${s.footerPlacement==='all'?'<tfoot><tr><td>'+footer+'</td></tr></tfoot>':''}<tbody><tr><td>${s.headerPlacement==='first'?header:''}${s.showBusinessName?'<h2>'+esc82(company)+'</h2>':''}<h1>${esc82(title)}</h1><p>${esc82(period)}</p>${content}${s.footerPlacement==='last'?footer:''}</td></tr></tbody></table></body></html>`;
}
function print82(title,content,period='',options={}){
 return openDocumentEditor105({title,category:/payroll|salary/i.test(title)?'Payroll':'Reports',printPreview:true,...options,html:`<h1>${esc82(title)}</h1>${period?`<p>${esc82(period)}</p>`:''}${content}`});
}
function payrollVoucher82(run,x){const leave=(run.leaveSnapshot||Work82.leaves.filter(r=>r.data.status==='approved'&&r.data.month===run.month).map(r=>r.data)).filter(r=>r.employeeId===x.employeeId);return `<article class="voucher82">${run.isSample?'<p class="notice82 warn82"><strong>SAMPLE — NOT FOR PAYMENT</strong></p>':''}<h2>Salary Payment Voucher · ${esc82(run.month)}</h2><p>${esc82(run.reference)} · ${run.status==='finalized'?'FINALIZED CALCULATION':'DRAFT — NOT FINALIZED'}</p><p><strong>${esc82(x.employee.name)}</strong> · ${esc82(x.employee.code)} · ${esc82(x.employee.position)}</p>${table82(['Description','Amount','Currency'],[['Contract salary',money82(x.contract),esc82(x.currency)],['LAK per 1 '+esc82(x.currency),money82(x.rate),'LAK'],['Overtime',money82(x.overtime),'LAK'],['Taxable allowance',money82(x.allowance),'LAK'],['Late time deduction',money82(x.late),'LAK'],['Unpaid days deduction ('+money82(x.unpaidDays)+' days)',money82(x.absence),'LAK'],['Other internal deductions',money82(x.penalty+x.other),'LAK'],['Gross earnings',money82(x.gross),'LAK'],['Employee SSO',money82(x.employeeSso),'LAK'],['Employee PIT',money82(x.employeePit),'LAK'],['Net pay',money82(x.net),'LAK'],['Reimbursement',money82(x.reimbursement),'LAK'],['Paid holiday / leave (already included)',money82(x.paidLeaveValue),'LAK'],['Less cash advance recovery',money82(x.cashAdvance??x.advance),'LAK'],['Less loan repayment',money82(x.loanRecovery),'LAK'],['Final amount to pay','<strong>'+money82(x.paidAmount)+'</strong>',esc82(x.currency)]])}<p>Rate date: ${esc82(run.rateDate)} · Source: ${esc82(run.rateSource||'LAK contract — no conversion')}<br>Approved leave: ${esc82(leave.map(l=>l.type+' '+l.days+' days ('+(l.paid==='yes'?'paid':'unpaid')+')').join('; ')||'None recorded')}. Paid leave is included in monthly salary.<br>Supporting reference: ${esc82(run.rows.find(r=>r.employeeId===x.employeeId)?.input.note||'—')}</p><p>I acknowledge receipt of __________________ ${esc82(x.currency)} on __________________.</p><div class="signatures82"><div>Employee signature</div><div>Authorized by</div><div>Witness / paid by</div></div><p>Printing this voucher does not mark the salary paid or post a journal entry.</p></article>`}
function printPayroll82(vouchers=false){try{if(!Work82.run)throw Error('Open a payroll run first.');if(Work82.run.status!=='finalized')updateRun82();const r=Work82.run,results=runResults82();const body=vouchers?results.map(x=>payrollVoucher82(r,x)).join(''):`<p>${esc82(r.reference)} · ${r.status==='finalized'?'FINALIZED':'DRAFT — NOT FINALIZED'}</p>${payrollSummary82(results)}${attendanceReport82(r)}${section82('Applied Settings',configSummary82(r.config||payrollConfig82()))}<p>Rate date: ${esc82(r.rateDate)} · Source: ${esc82(r.rateSource||'No currency conversion')}<br>${esc82(r.notes)}</p><div class="signatures82"><div>Prepared by: ${esc82(r.finalizedBy||liveProfile.full_name||liveProfile.email)}</div><div>Reviewed / approved by</div></div>`;print82(vouchers?'Salary Vouchers':'Payroll Register',body,r.month)}catch(e){showCenterStatus(e.message,true)}}
function printLeave82(){const rows=[...Work82.leaves].sort((a,b)=>a.data.from.localeCompare(b.data.from));print82('Employee Leave Report',section82('Current Entitlements',table82(['Employee','Vacation available','Vacation used','Sick used','Personal used','Bereavement used','Period begins'],Work82.employees.map(leaveSummary82)))+section82('Leave Records',table82(['Employee','Dates','Type','Days','Paid','Informed / form','Status','Reason / reference'],rows.map(r=>{const d=r.data;return[esc82(Work82.employees.find(e=>e.id===d.employeeId)?.data.name||'Former employee'),esc82(d.from+' – '+d.to),esc82(d.type),money82(d.days),d.paid==='yes'?'Yes':'No',(d.informed?'Yes':'No')+' / '+(d.formReceived?'Yes':'No'),esc82(d.status),esc82(d.notes+' · '+d.reference)]}))),today82())}
function printOperational82(){try{const d=Work82.reportRecord?.data.kind==='subuser'?Work82.reportRecord.data:buildSubReport82();if(d)print82(d.type==='petty'?'Petty Cash Liquidation':'Daily Shift Cover Sheet',subReportHtml82(d,true),d.from+' to '+d.to)}catch(e){showCenterStatus(e.message,true)}}
