async function newFinance82(){if(!await ui117.confirm('Start a new financing report? Save the current report first if needed.'))return;Object.assign(Finance82,{reference:'',date:today82(),recipient:'',purpose:'',mode:'request',notes:'',reviewer:'',lines:[],movements:[],conversions:[]});Work82.reportRecord=null;Work82.report=null;renderWork82()}
function exportDraft82(kind){if(kind==='payroll')updateRun82();const data=kind==='payroll'?Work82.run:Work82.report;if(!data)return;const blob=new Blob([JSON.stringify({format:'oonjai-backup-82',kind,data},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=kind+'-'+today82()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function importDraft82(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file||file.size>5e6)throw Error('Choose a payroll backup under 5 MB.');const parsed=JSON.parse(await file.text());if(parsed.format!=='oonjai-backup-82'||parsed.kind!=='payroll'||!Array.isArray(parsed.data?.rows)||!/^\d{4}-\d{2}$/.test(parsed.data.month))throw Error('This is not a payroll backup.');for(const r of parsed.data.rows)if(!r.employeeId||!r.employee?.name||!r.employee.currency||!Array.isArray(r.input?.attendance))throw Error('Backup contains an invalid employee row.');Work82.run={...parsed.data,status:'draft',reviewed:false};delete Work82.run.results;delete Work82.run.config;delete Work82.run.finalizedAt;Work82.runRecord=null;switchTab('payroll-entries');showCenterStatus('Restored as a draft. Review Settings and save to create a new record.')}catch(e){showCenterStatus(e.message,true)}};input.click()}

function schedule82(month=today82().slice(0,7)){const c=payrollConfig82(),t=ApplicationSettings.tax,day=(m,n)=>{const [y,mo]=m.split('-').map(Number);return date71(y,mo,Math.min(Number(n)||1,new Date(y,mo,0).getDate()))},[y,m]=month.split('-').map(Number),next=date71(m===12?y+1:y,m===12?1:m+1,1).slice(0,7);return section82('Payroll & Filing Schedule',table82(['Item','Date','Reminder begins','Posting reference'],[['Payroll cutoff',esc82(formatAppDate(day(month,c.cutoff))),'—','Schedule reference; attendance uses the selected payroll month'],['Salary payment day',esc82(formatAppDate(day(month,c.paymentDay))),'—','Planned date; payment is recorded separately'],...['pit','sso'].map(k=>{const due=day(next,t[k+'Deadline']),d=new Date(due+'T12:00:00');d.setDate(d.getDate()-Number(t[k+'ReminderDays']||0));return[k.toUpperCase()+' · following-month reference',esc82(formatAppDate(due)),esc82(formatAppDate(date71(d.getFullYear(),d.getMonth()+1,d.getDate()))),esc82(t[k+'Account'])]})]))+'<p class="notice82">Dates follow your saved settings. This is an on-screen schedule, not a filing service or an automatic payment reminder.</p>'}
