function auditHtml82(){return `<p>Version 82 · Desktop payroll and operational reports. No saved PIT or SSO values were replaced.</p><p>Reference PDFs were used for layout and workflow only. The Ryan PDF category summary omits a 5,000 transport item; this implementation derives category totals and details from the same source records. The shift PDF mixes month labels; report headings use the selected dates. Sample employee or payroll figures have not been imported.</p>`+table82(['Area','Settings','Integration','Behavior / remaining work'],audit82.map(r=>r.map(esc82)))+`<p>Database setup is required to save employees, leave, payroll runs and report snapshots. The setup adds four named tables with admin-only access, revision checks and immutable finalized payroll. It does not alter your existing transactions or settings. It has not been run by this update.</p><p>Pure ledger reports are calculated from transactions. Manual leave, attendance, explanations, POS totals and financing requests need saved records; they cannot reliably be reconstructed from journal entries alone.</p>`}
function renderSettingsAudit82(){mount82('settings-integration82','Settings Integration Audit','What is connected, what is reference-only, and what still needs a workflow.',auditHtml82(),'<a class="download82" href="setup/SETUP-GUIDE-v142.20.txt" download>Update Report</a><a class="download82" href="setup/SETUP-GUIDE-v142.20.txt" download>Database Setup</a>'+action82('Print Audit',"print82('Settings Integration Audit',auditHtml82(),today82())"))}
function linkSsoFields82(){if(!desktop80.matches)return;const form=document.querySelector('[data-settings-group="payroll"]');if(!form)return;for(const [field,key]of [['employeeSsoRate','ssoEmployeeRate'],['employerSsoRate','ssoEmployerRate']]){const n=form.elements.namedItem(field);if(n){n.value=ApplicationSettings.tax[key];n.readOnly=true;n.title='Maintained in Statutory Settings'}}if(!document.getElementById('ssoSource82')){const p=document.createElement('p');p.id='ssoSource82';p.className='notice82 only-desktop82';p.textContent='SSO rates are maintained in Statutory Settings. Payroll uses those rates and the statutory contribution ceiling.';form.prepend(p)}}
const saveSettingsBefore82=saveSettingsGroup;saveSettingsGroup=function(event){const form=event.currentTarget,group=form.dataset.settingsGroup;if(desktop80.matches&&['tax','payroll'].includes(group)){try{const draft=structuredClone(ApplicationSettings);draft[group]={...draft[group],...collectSettingsForm(form)};payrollConfig82(draft)}catch(e){event.preventDefault();return showAppNotification('Review Settings',e.message,true)}}const result=saveSettingsBefore82(event);linkSsoFields82();if(Work82.run?.status==='draft'){Work82.run.reviewed=false;const review=document.querySelector('#runMeta82 [name=reviewed]');if(review)review.checked=false;updateRun82()}return result};
const printBefore82=printDesktopReport79;printDesktopReport79=function(kind){if(!desktop80.matches)return printBefore82(kind);print82(reportNames79[kind],`<p>Posted journal · ${esc82(Reports79.from)} – ${esc82(Reports79.to)}</p>`+reportContent79(kind,true)+(Reports79.notes[kind]?'<h3>Notes / findings</h3><p>'+esc82(Reports79.notes[kind])+'</p>':''),Reports79.from+' to '+Reports79.to)};
const switchWorkBefore82=switchTab;switchTab=function(id,...args){if(Work82.run?.status==='draft'&&document.querySelector('#payroll-entries.active,#payroll-deductions.active'))updateRun82();const result=switchWorkBefore82(id,...args);if(desktop80.matches){renderWork82();if(['payroll-overview','payroll-employees','payroll-entries','payroll-deductions','payroll-history','report-subusers82','report-financing82','report-payroll'].includes(id))loadWork82();if(id==='settings-payroll')linkSsoFields82()}return result};
