function bindRun(){const f=document.getElementById('runMeta95');if(f)f.onchange=e=>{if(e.target.name==='month'){const month=e.target.value;updateRun82();selectMonth(month);renderWork82()}else{updateRun82();if(e.target.name!=='reviewed'){Work82.run.reviewed=false;softRender95()}}};document.querySelectorAll('[data-row95][data-field95]').forEach(n=>n.onchange=()=>{updateRun82();Work82.run.reviewed=false;softRender95()});document.querySelectorAll('[data-att-row95]').forEach(n=>{n.onchange=()=>{updateRun82();try{parseMark(n.value);n.setCustomValidity('');const row=Work82.run.rows[Number(n.dataset.attRow95)],date=n.dataset.date95;let a=row.input.attendance.find(a=>a.date===date);if(!a){a={date,late:0,overtime:0};row.input.attendance.push(a)}a.mark95=n.value.trim().toUpperCase()||'0';a.late=0;Work82.run.reviewed=false;softRender95()}catch(e){n.setCustomValidity(e.message);n.reportValidity()}};n.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();n.blur()}}})}
