window.payDay95=function(i,date){updateRun82();const run=Work82.run;if(!run||run.status==='finalized')return;const row=run.rows[i],a=row.input.attendance.find(a=>a.date===date)||{date,late:0,overtime:0},over=a.override95;const currencies=CurrencyStore.currencies.map(c=>[c.code,c.code]);const root=modal('payDay95','Attendance — '+row.employee.code+' · '+date,`<form><div class="fields82">${field82('Minutes / code','mark',mark(a),'text','required')}${field82('Overtime hours','overtime',a.overtime||0,'number','min="0" max="24" step="0.25"')}${field82('Attendance note','note',a.note||'')}${check82('Replace this day’s entire deduction with a manual amount','override',Boolean(over))}${field82('Manual deduction amount','amount',over?.amount??0,'number','min="0" step="0.01"')}${select82('Currency','currency',over?.currency||'LAK',currencies)}${field82('Reason for manual override','reason',over?.reason||'')}</div><p>This replaces the day’s time, penalty and code deduction. It does not add another charge. Approved unpaid leave must be corrected in its leave record first.</p><p role="alert"></p><footer><button type="submit" class="primary82">Save Day</button></footer></form>`);root.querySelector('form').onsubmit=e=>{e.preventDefault();try{const f=e.currentTarget,d=Object.fromEntries(new FormData(f));parseMark(d.mark);if(f.elements.override.checked&&!d.reason.trim())throw Error('Enter a reason for the manual deduction.');const next={...a,mark95:d.mark.trim().toUpperCase(),late:0,overtime:number(d.overtime,'Overtime'),note:d.note};if(f.elements.override.checked)next.override95={amount:number(d.amount,'Manual deduction'),currency:d.currency,reason:d.reason.trim()};else delete next.override95;const index=row.input.attendance.findIndex(a=>a.date===date);if(index<0)row.input.attendance.push(next);else row.input.attendance[index]=next;run.reviewed=false;root.remove();renderWork82()}catch(e){root.querySelector('[role=alert]').textContent=e.message}}};
window.openLegend95=function(){let draft=structuredClone(legends());const root=modal('legend95','Attendance Legend Settings','<div id="legendEditor95"></div>');function read(){root.querySelectorAll('[data-legend-row95]').forEach(tr=>{const r=draft[Number(tr.dataset.legendRow95)];tr.querySelectorAll('[data-key95]').forEach(n=>r[n.dataset.key95]=n.value)})}function draw(){root.querySelector('#legendEditor95').innerHTML=`<p>One configuration is shared by Payroll and Settings. Percentage means deduction from daily salary (monthly salary ÷ working days). 0% = paid, 50% = half pay, 100% = unpaid. Fixed amounts apply per occurrence.</p><div class="data-table82"><table><thead><tr>${['Code','Description','Deduction method','Value','Currency','Late minutes','Color',''].map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${draft.map((r,i)=>`<tr data-legend-row95="${i}"><td><input data-key95="code" value="${esc(r.code)}" maxlength="12" aria-label="Code ${i+1}"></td><td><textarea data-key95="description" rows="2" aria-label="Description ${i+1}">${esc(r.description)}</textarea></td><td><select data-key95="method">${[['percent','% of daily salary'],['fixed','Fixed amount'],['manual','Manual per occurrence']].map(([v,t])=>`<option value="${v}" ${r.method===v?'selected':''}>${t}</option>`).join('')}</select></td><td><input data-key95="value" type="number" min="0" step="0.01" value="${r.value}" aria-label="Deduction value ${i+1}"><span data-unit95 hidden>%</span><span data-manual-hint95 hidden>Enter on attendance day</span></td><td data-currency-cell95 hidden><select data-key95="currency">${CurrencyStore.currencies.map(c=>`<option ${r.currency===c.code?'selected':''}>${esc(c.code)}</option>`).join('')}</select></td><td><select data-key95="lateMode"><option value="exempt" ${r.lateMode==='exempt'?'selected':''}>Exempt</option><option value="normal" ${r.lateMode==='normal'?'selected':''}>Apply grace / penalty</option></select></td><td><input data-key95="color" type="color" value="${esc(r.color||'#166534')}"></td><td><button type="button" data-remove95="${i}">Remove</button></td></tr>`).join('')}</tbody></table></div><p>Use CODE:minutes when a code includes late minutes. Manual per-occurrence amounts are entered through attendance day details. Leave balances remain managed through employee leave settings and approved leave records.</p><p role="alert"></p><footer><button type="button" id="addLegend95">Add Legend</button><button type="button" id="saveLegend95" class="primary82">Save Legend Settings</button></footer>`;root.querySelectorAll('[data-legend-row95]').forEach(tr=>{const sync=()=>{const method=tr.querySelector('[data-key95=\"method\"]').value;tr.querySelector('[data-currency-cell95]').style.display=method==='fixed'?'':'none';tr.querySelector('[data-key95=\"value\"]').style.display=method==='manual'?'none':'';tr.querySelector('[data-unit95]').style.display=method==='percent'?'':'none';tr.querySelector('[data-manual-hint95]').style.display=method==='manual'?'':'none'};sync();tr.querySelector('[data-key95=\"method\"]').onchange=sync});root.querySelector('#addLegend95').onclick=()=>{read();draft.push({code:'',description:'',method:'percent',value:0,currency:'LAK',leaveType:'',lateMode:'exempt',color:'#166534'});draw()};root.querySelectorAll('[data-remove95]').forEach(b=>b.onclick=()=>{read();draft.splice(Number(b.dataset.remove95),1);draw()});root.querySelector('#saveLegend95').onclick=()=>{try{read();const used=new Set();for(const r of draft){r.code=r.code.trim().toUpperCase();r.description=r.description.trim();r.value=number(r.value,'Legend value');if(!/^[A-Z][A-Z0-9]{0,11}$/.test(r.code)||used.has(r.code))throw Error('Codes must be unique, start with a letter and contain only letters/numbers.');used.add(r.code);if(!r.description)throw Error('Every code needs a description.');if(r.method==='percent'&&r.value>100)throw Error('Percentage must be between 0 and 100.');if(!/^#[a-f0-9]{6}$/i.test(r.color))throw Error('Choose a valid color.');}
 for(const run of [Work82.run,...Work82.runs.map(x=>x.data)].filter(r=>r&&r.status==='draft'))for(const row of run.rows)for(const a of row.input.attendance||[])parseMark(mark(a),draft);
 ApplicationSettings.payroll.attendanceLegend95=draft;localStorage.setItem(APP_SETTINGS_KEY,JSON.stringify(ApplicationSettings));if(Work82.run?.status==='draft')Work82.run.reviewed=false;root.remove();renderWork82();showCenterStatus('Legend settings saved in both locations.');}catch(e){root.querySelector('[role=alert]').textContent=e.message}}}draw()};
