const priorLeaveStatus95=leaveStatus82;window.leaveStatus82=function(id,status){if(status==='approved'){const rec=Work82.leaves.find(l=>l.id===id),e=Work82.employees.find(e=>e.id===rec?.data.employeeId);if(rec&&e&&rec.data.paid==='yes'&&!['absent','other'].includes(rec.data.type)){const types=rec.data.type==='minorSick'?['minorSick','sick']:[rec.data.type];for(const type of types){const used=Work82.leaves.filter(l=>l.id!==id&&l.data.employeeId===e.id&&l.data.status==='approved'&&l.data.from>=e.data.renewal&&(l.data.type===type||type==='sick'&&l.data.type==='minorSick')).reduce((n,l)=>n+Number(l.data.days),0)+usedLegendLeave(e.id,type,e.data.renewal);const limit=Number(e.data[type]??ApplicationSettings.payroll[type+'Allowance']??0);if(used+Number(rec.data.days)>limit)return showCenterStatus('This exceeds '+e.data.name+'’s '+type+' allowance, including finalized attendance.',true)}}}return priorLeaveStatus95(id,status)};
