 window.updateHeaderProfile104=function(){const node=$('headerAccountInitials'),name=$('currentUserChip'),role=$('sidebarUserRole');if(!node)return;const person=typeof liveProfile!=='undefined'&&liveProfile;const display=person?.full_name||DemoAccess.currentUser?.name||'Signed-in user';if(name)name.textContent=display;if(role)role.textContent=String(person?.role||'Account user').replace(/_/g,' ');const photo=window.shell113?.state.photo||profile()?.photoData||localStorage.getItem('ojm_company_logo101')||'';if(photo&&/^data:image\/(?:png|jpeg|webp);base64,/i.test(photo)){let img=node.querySelector('img');if(!img){node.textContent='';img=document.createElement('img');img.alt='';node.append(img)}if(img.src!==photo)img.src=photo;node.classList.add('has-photo104')}else{node.classList.remove('has-photo104');node.textContent=display.trim().split(/\s+/).slice(0,2).map(s=>s[0]||'').join('').toUpperCase()||'OJ'}};
