 document.body.append(box);box.querySelector('[data-documents]')?.addEventListener('click',()=>{box.remove();openDocumentEditor105({employeeId:e.id,list:true})});box.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>box.remove());box.querySelector('[data-edit]')?.addEventListener('click',()=>{box.remove();switchTab('payroll-employees');openEmployee82(e.id)});box.addEventListener('click',e=>{if(e.target===box)box.remove()});box.querySelector('button').focus();box.onkeydown=e=>{if(e.key==='Escape')box.remove()};
